export { default as LayerSeparator } from "./LayerSeparator";
export type {
  LayerSeparatorAsset,
  LayerSeparatorBoundingBox,
  LayerSeparatorFrame,
  LayerSeparatorLabels,
  LayerSeparatorProps,
  LayerSeparatorRequest,
  LayerSeparatorResult,
  LayerSeparatorSelection,
  LayerSeparatorTransform,
} from "./LayerSeparator.types";
export {
  buildLayerSeparatorPrompt,
  composeLayerSeparatorResult,
  isUsableSelection,
  normalizeResult,
  normalizeTransform,
  toBoundingBox,
} from "./LayerSeparator.utils";

import {
  Eye,
  EyeOff,
  Layers3,
  LoaderCircle,
  RotateCcw,
  Sparkles,
  Undo2,
  Redo2,
  X,
} from "lucide-react";
import {
  useEffect,
  useMemo,
  useRef,
  useState,
  type PointerEvent as ReactPointerEvent,
} from "react";
import type {
  LayerSeparatorLabels,
  LayerSeparatorProps,
  LayerSeparatorResult,
  LayerSeparatorSelection,
  LayerSeparatorTransform,
} from "./LayerSeparator.types";
import {
  buildLayerSeparatorPrompt,
  composeLayerSeparatorResult,
  isUsableSelection,
  normalizeResult,
  normalizeTransform,
  toBoundingBox,
} from "./LayerSeparator.utils";
import CompositionStage from "./parts/CompositionStage";
import SelectionStage from "./parts/SelectionStage";
import "./LayerSeparator.css";

const COPY: Record<"zh-CN" | "en-US", LayerSeparatorLabels> = {
  "zh-CN": {
    title: "图层分离",
    description: "框选画面元素，或让模型自动识别主体",
    selectionHint: "拖拽框选想要拆分的物体",
    instructionLabel: "分层说明",
    instructionPlaceholder: "描述想拆出的图层；留空将自动识别主体",
    automatic: "自动拆分",
    separate: "开始分层",
    cancel: "取消",
    reset: "重新框选",
    working: "正在识别图层",
    background: "背景层",
    layers: "分离图层",
    merge: "合并并导出",
    editHint: "拖动图层调整位置，使用浮动工具旋转或翻转",
    emptyLayers: "服务已返回背景图，但没有可编辑图层。",
  },
  "en-US": {
    title: "Layer separator",
    description: "Select objects, or let the model find the main subjects",
    selectionHint: "Drag to select objects to separate",
    instructionLabel: "Layer instructions",
    instructionPlaceholder: "Describe the layers to extract, or leave blank for automatic detection",
    automatic: "Auto separate",
    separate: "Separate layers",
    cancel: "Cancel",
    reset: "Select again",
    working: "Detecting layers",
    background: "Background",
    layers: "Separated layers",
    merge: "Merge and export",
    editHint: "Drag a layer to move it. Use the floating controls to rotate or flip.",
    emptyLayers: "The service returned a background without editable layers.",
  },
};

function readPointerRatio(event: ReactPointerEvent<HTMLDivElement>, element: HTMLDivElement) {
  const rect = element.getBoundingClientRect();
  return {
    x: Math.min(1, Math.max(0, (event.clientX - rect.left) / rect.width)),
    y: Math.min(1, Math.max(0, (event.clientY - rect.top) / rect.height)),
  };
}

export default function LayerSeparator({
  imageUrl,
  imageAlt = "",
  aspectRatio = 1,
  defaultSelections = [],
  result,
  defaultResult = null,
  locale = "zh-CN",
  labels,
  onSeparate,
  onResultChange,
  onMerge,
  onCancel,
  onError,
  className,
  style,
}: LayerSeparatorProps) {
  const copy = useMemo(() => ({ ...COPY[locale], ...labels }), [labels, locale]);
  const stageRef = useRef<HTMLDivElement | null>(null);
  const selectionSequence = useRef(defaultSelections.length);
  const [selections, setSelections] = useState(defaultSelections);
  const [draft, setDraft] = useState<LayerSeparatorSelection | null>(null);
  const [undoStack, setUndoStack] = useState<LayerSeparatorSelection[][]>([]);
  const [redoStack, setRedoStack] = useState<LayerSeparatorSelection[][]>([]);
  const [instruction, setInstruction] = useState("");
  const [internalResult, setInternalResult] = useState<LayerSeparatorResult | null>(() =>
    defaultResult ? normalizeResult(defaultResult) : null,
  );
  const [selectedLayerId, setSelectedLayerId] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [merging, setMerging] = useState(false);
  const [progress, setProgress] = useState(8);
  const [error, setError] = useState<string | null>(null);
  const resolvedResult = useMemo(
    () => (result !== undefined ? (result ? normalizeResult(result) : null) : internalResult),
    [internalResult, result],
  );

  useEffect(() => {
    if (!submitting) return;
    setProgress(8);
    const timer = window.setInterval(() => {
      setProgress((current) => Math.min(94, current + Math.max(1, Math.ceil((94 - current) * 0.08))));
    }, 620);
    return () => window.clearInterval(timer);
  }, [submitting]);

  useEffect(() => {
    setSelectedLayerId((current) => {
      if (current && resolvedResult?.layers.some((layer) => layer.id === current)) return current;
      return resolvedResult?.layers[0]?.id ?? null;
    });
  }, [resolvedResult]);

  const commitSelections = (next: LayerSeparatorSelection[]) => {
    setUndoStack((current) => [...current, selections]);
    setRedoStack([]);
    setSelections(next);
  };

  const handlePointerDown = (event: ReactPointerEvent<HTMLDivElement>) => {
    if (event.button !== 0 || !stageRef.current || submitting) return;
    event.preventDefault();
    event.currentTarget.setPointerCapture(event.pointerId);
    const point = readPointerRatio(event, stageRef.current);
    selectionSequence.current += 1;
    setDraft({
      id: `selection-${selectionSequence.current}`,
      x1: point.x,
      y1: point.y,
      x2: point.x,
      y2: point.y,
    });
  };

  const handlePointerMove = (event: ReactPointerEvent<HTMLDivElement>) => {
    if (!draft || !stageRef.current) return;
    const point = readPointerRatio(event, stageRef.current);
    setDraft((current) => (current ? { ...current, x2: point.x, y2: point.y } : null));
  };

  const handlePointerUp = (event: ReactPointerEvent<HTMLDivElement>) => {
    if (!draft) return;
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }
    if (isUsableSelection(draft)) commitSelections([...selections, draft]);
    setDraft(null);
  };

  const undo = () => {
    const previous = undoStack[undoStack.length - 1];
    if (!previous) return;
    setUndoStack((current) => current.slice(0, -1));
    setRedoStack((current) => [selections, ...current]);
    setSelections(previous);
  };

  const redo = () => {
    const next = redoStack[0];
    if (!next) return;
    setRedoStack((current) => current.slice(1));
    setUndoStack((current) => [...current, selections]);
    setSelections(next);
  };

  const updateResult = (next: LayerSeparatorResult) => {
    const normalized = normalizeResult(next);
    if (result === undefined) setInternalResult(normalized);
    onResultChange?.(normalized);
  };

  const separate = async () => {
    if (!onSeparate || submitting) return;
    const boxes = selections.map(toBoundingBox);
    setError(null);
    setSubmitting(true);
    try {
      const next = await onSeparate({
        selections: boxes,
        instruction: instruction.trim(),
        prompt: buildLayerSeparatorPrompt(boxes, instruction),
      });
      if (next) updateResult(next);
    } catch (cause) {
      const nextError = cause instanceof Error ? cause : new Error(String(cause));
      setError(nextError.message);
      onError?.(nextError);
    } finally {
      setSubmitting(false);
    }
  };

  const patchLayer = (id: string, transform: LayerSeparatorTransform) => {
    if (!resolvedResult) return;
    updateResult({
      ...resolvedResult,
      layers: resolvedResult.layers.map((layer) =>
        layer.id === id ? { ...layer, transform } : layer,
      ),
    });
  };

  const reset = () => {
    if (result === undefined) setInternalResult(null);
    setSelections([]);
    setUndoStack([]);
    setRedoStack([]);
    setInstruction("");
    setError(null);
  };

  const merge = async () => {
    if (!resolvedResult || merging) return;
    setMerging(true);
    setError(null);
    try {
      const blob = await composeLayerSeparatorResult(resolvedResult);
      if (onMerge) onMerge(blob, resolvedResult);
      else {
        const url = URL.createObjectURL(blob);
        const anchor = document.createElement("a");
        anchor.href = url;
        anchor.download = "layer-composition.png";
        anchor.click();
        URL.revokeObjectURL(url);
      }
    } catch (cause) {
      const nextError = cause instanceof Error ? cause : new Error(String(cause));
      setError(nextError.message);
      onError?.(nextError);
    } finally {
      setMerging(false);
    }
  };

  return (
    <section
      data-slot="layer-separator"
      className={["layer-separator", className].filter(Boolean).join(" ")}
      style={style}
      aria-label={copy.title}
    >
      <header className="layer-separator__header">
        <div className="layer-separator__heading">
          <span className="layer-separator__mark"><Layers3 size={18} /></span>
          <span><strong>{copy.title}</strong><small>{copy.description}</small></span>
        </div>
        <div className="layer-separator__history" aria-label="History controls">
          <button type="button" onClick={undo} disabled={Boolean(resolvedResult) || undoStack.length === 0} aria-label="Undo"><Undo2 size={16} /></button>
          <button type="button" onClick={redo} disabled={Boolean(resolvedResult) || redoStack.length === 0} aria-label="Redo"><Redo2 size={16} /></button>
          <button type="button" onClick={onCancel ?? reset} aria-label={copy.cancel}><X size={17} /></button>
        </div>
      </header>

      <div className="layer-separator__body">
        <main className="layer-separator__workspace">
          <div className="layer-separator__stage-wrap">
            {resolvedResult ? (
              <CompositionStage
                result={resolvedResult}
                aspectRatio={aspectRatio}
                backgroundLabel={copy.background}
                selectedId={selectedLayerId}
                onSelect={setSelectedLayerId}
                onChange={patchLayer}
              />
            ) : (
              <SelectionStage
                stageRef={stageRef}
                imageUrl={imageUrl}
                imageAlt={imageAlt}
                aspectRatio={aspectRatio}
                selections={selections}
                draft={draft}
                hint={copy.selectionHint}
                onPointerDown={handlePointerDown}
                onPointerMove={handlePointerMove}
                onPointerUp={handlePointerUp}
                onPointerCancel={() => setDraft(null)}
              />
            )}
            {submitting ? (
              <div className="layer-separator__loading" role="progressbar" aria-valuemin={0} aria-valuemax={100} aria-valuenow={progress}>
                <LoaderCircle size={22} />
                <span>{copy.working}</span><strong>{progress}%</strong>
              </div>
            ) : null}
          </div>
        </main>

        <aside className="layer-separator__panel">
          {resolvedResult ? (
            <>
              <div className="layer-separator__panel-heading"><span>{copy.layers}</span><small>{resolvedResult.layers.length}</small></div>
              <p className="layer-separator__edit-hint">{copy.editHint}</p>
              <div className="layer-separator__layer-list">
                <div className="layer-separator__layer-row is-background"><span className="layer-separator__layer-index">B</span><span>{resolvedResult.background.name ?? copy.background}</span></div>
                {resolvedResult.layers.map((layer, index) => {
                  const transform = normalizeTransform(layer.transform);
                  return (
                    <div key={layer.id} className={["layer-separator__layer-row", selectedLayerId === layer.id ? "is-selected" : ""].join(" ")}>
                      <button type="button" className="layer-separator__layer-main" onClick={() => setSelectedLayerId(layer.id)}>
                        <span className="layer-separator__layer-index">{String(index + 1).padStart(2, "0")}</span>
                        <span>{layer.name ?? `Layer ${index + 1}`}</span>
                      </button>
                      <button type="button" className="layer-separator__visibility" aria-label={transform.visible ? "Hide layer" : "Show layer"} onClick={() => patchLayer(layer.id, { ...transform, visible: !transform.visible })}>
                        {transform.visible ? <Eye size={15} /> : <EyeOff size={15} />}
                      </button>
                    </div>
                  );
                })}
                {resolvedResult.layers.length === 0 ? <p className="layer-separator__empty">{copy.emptyLayers}</p> : null}
              </div>
              {selectedLayerId ? (() => {
                const selected = resolvedResult.layers.find((layer) => layer.id === selectedLayerId);
                if (!selected) return null;
                const transform = normalizeTransform(selected.transform);
                return (
                  <label className="layer-separator__scale">
                    <span>Scale <output>{Math.round(transform.width * 100)}%</output></span>
                    <input type="range" min="20" max="160" value={Math.round(transform.width * 100)} onChange={(event) => {
                      const width = Number(event.target.value) / 100;
                      patchLayer(selected.id, { ...transform, width, height: transform.height * (width / transform.width) });
                    }} />
                  </label>
                );
              })() : null}
              <div className="layer-separator__panel-actions">
                <button type="button" className="layer-separator__secondary" onClick={reset}><RotateCcw size={15} />{copy.reset}</button>
                <button type="button" className="layer-separator__primary" disabled={merging} onClick={() => void merge()}>{merging ? <LoaderCircle className="is-spinning" size={15} /> : <Layers3 size={15} />}{copy.merge}</button>
              </div>
            </>
          ) : (
            <>
              <div className="layer-separator__panel-heading"><span>{copy.instructionLabel}</span><small>{selections.length}</small></div>
              <div className="layer-separator__selection-list">
                {selections.map((selection, index) => {
                  const left = Math.min(selection.x1, selection.x2);
                  const top = Math.min(selection.y1, selection.y2);
                  const width = Math.max(0.001, Math.abs(selection.x2 - selection.x1));
                  const height = Math.max(0.001, Math.abs(selection.y2 - selection.y1));
                  return (
                    <button key={selection.id} type="button" aria-label={`Remove selection ${index + 1}`} onClick={() => commitSelections(selections.filter((item) => item.id !== selection.id))}>
                      <span style={{ backgroundImage: `url(${imageUrl})`, backgroundSize: `${100 / width}% ${100 / height}%`, backgroundPosition: `${(-left / width) * 100}% ${(-top / height) * 100}%` }} />
                      <strong>{String(index + 1).padStart(2, "0")}</strong><X size={13} />
                    </button>
                  );
                })}
              </div>
              <textarea value={instruction} rows={5} placeholder={copy.instructionPlaceholder} aria-label={copy.instructionLabel} onChange={(event) => setInstruction(event.target.value)} />
              {error ? <p className="layer-separator__error" role="alert">{error}</p> : null}
              <div className="layer-separator__panel-actions">
                <button type="button" className="layer-separator__secondary" disabled={submitting} onClick={onCancel ?? reset}>{copy.cancel}</button>
                <button type="button" className="layer-separator__primary" disabled={submitting || !onSeparate} onClick={() => void separate()}><Sparkles size={15} />{selections.length ? `${copy.separate} · ${selections.length + 1}` : copy.automatic}</button>
              </div>
            </>
          )}
          {error && resolvedResult ? <p className="layer-separator__error" role="alert">{error}</p> : null}
        </aside>
      </div>
    </section>
  );
}

import type { CSSProperties } from "react";

export type LayerSeparatorSelection = {
  id: string;
  x1: number;
  y1: number;
  x2: number;
  y2: number;
};

export type LayerSeparatorBoundingBox = {
  x1: number;
  y1: number;
  x2: number;
  y2: number;
};

export type LayerSeparatorFrame = {
  x: number;
  y: number;
  width: number;
  height: number;
};

export type LayerSeparatorTransform = LayerSeparatorFrame & {
  rotation: number;
  flipX: boolean;
  flipY: boolean;
  visible: boolean;
};

export type LayerSeparatorAsset = {
  id: string;
  name?: string;
  url: string;
  /** The visible subject bounds inside a full-canvas transparent asset. */
  contentBounds?: LayerSeparatorFrame;
  /** Defaults to a full-canvas transform. */
  transform?: Partial<LayerSeparatorTransform>;
};

export type LayerSeparatorResult = {
  background: LayerSeparatorAsset;
  layers: LayerSeparatorAsset[];
};

export type LayerSeparatorRequest = {
  selections: LayerSeparatorBoundingBox[];
  instruction: string;
  prompt: string;
};

export type LayerSeparatorLabels = {
  title: string;
  description: string;
  selectionHint: string;
  instructionLabel: string;
  instructionPlaceholder: string;
  automatic: string;
  separate: string;
  cancel: string;
  reset: string;
  working: string;
  background: string;
  layers: string;
  merge: string;
  editHint: string;
  emptyLayers: string;
};

export type LayerSeparatorProps = {
  imageUrl: string;
  imageAlt?: string;
  aspectRatio?: number;
  defaultSelections?: LayerSeparatorSelection[];
  result?: LayerSeparatorResult | null;
  defaultResult?: LayerSeparatorResult | null;
  locale?: "zh-CN" | "en-US";
  labels?: Partial<LayerSeparatorLabels>;
  onSeparate?: (
    request: LayerSeparatorRequest,
  ) => Promise<LayerSeparatorResult | void> | LayerSeparatorResult | void;
  onResultChange?: (result: LayerSeparatorResult) => void;
  onMerge?: (blob: Blob, result: LayerSeparatorResult) => void;
  onCancel?: () => void;
  onError?: (error: Error) => void;
  className?: string;
  style?: CSSProperties;
};

import type {
  LayerSeparatorBoundingBox,
  LayerSeparatorResult,
  LayerSeparatorSelection,
  LayerSeparatorTransform,
} from "./LayerSeparator.types";

const COORDINATE_MAX = 999;

export function clamp(value: number, min = 0, max = 1) {
  return Math.min(max, Math.max(min, value));
}

export function isUsableSelection(selection: LayerSeparatorSelection) {
  return (
    Math.abs(selection.x2 - selection.x1) >= 0.015 &&
    Math.abs(selection.y2 - selection.y1) >= 0.015
  );
}

export function toBoundingBox(
  selection: LayerSeparatorSelection,
): LayerSeparatorBoundingBox {
  const normalize = (value: number) =>
    Math.min(COORDINATE_MAX, Math.max(0, Math.round(clamp(value) * 1000)));
  return {
    x1: normalize(Math.min(selection.x1, selection.x2)),
    y1: normalize(Math.min(selection.y1, selection.y2)),
    x2: normalize(Math.max(selection.x1, selection.x2)),
    y2: normalize(Math.max(selection.y1, selection.y2)),
  };
}

export function buildLayerSeparatorPrompt(
  boxes: LayerSeparatorBoundingBox[],
  instruction = "",
) {
  const target = boxes.length
    ? `the objects within ${boxes
        .map((box) => `<bbox>${box.x1} ${box.y1} ${box.x2} ${box.y2}</bbox>`)
        .join(" and ")}`
    : "the main objects in the image";
  const base = `Split ${target} into separate editable transparent layers, and keep the background as the base layer.`;
  const detail = instruction.trim();
  return detail ? `${detail}\n${base}` : base;
}

export function normalizeTransform(
  transform: Partial<LayerSeparatorTransform> | undefined,
): LayerSeparatorTransform {
  return {
    x: clamp(transform?.x ?? 0, -1, 1),
    y: clamp(transform?.y ?? 0, -1, 1),
    width: clamp(transform?.width ?? 1, 0.04, 2),
    height: clamp(transform?.height ?? 1, 0.04, 2),
    rotation: Number.isFinite(transform?.rotation) ? transform!.rotation! : 0,
    flipX: transform?.flipX ?? false,
    flipY: transform?.flipY ?? false,
    visible: transform?.visible ?? true,
  };
}

export function normalizeResult(result: LayerSeparatorResult) {
  return {
    ...result,
    layers: result.layers.map((layer) => ({
      ...layer,
      transform: normalizeTransform(layer.transform),
    })),
  } satisfies LayerSeparatorResult;
}

async function loadImage(url: string) {
  const image = new Image();
  image.crossOrigin = "anonymous";
  image.src = url;
  await image.decode();
  return image;
}

export async function composeLayerSeparatorResult(result: LayerSeparatorResult) {
  const background = await loadImage(result.background.url);
  const canvas = document.createElement("canvas");
  canvas.width = background.naturalWidth || background.width;
  canvas.height = background.naturalHeight || background.height;
  const context = canvas.getContext("2d");
  if (!context) throw new Error("Unable to create the layer composition canvas.");

  context.imageSmoothingEnabled = true;
  context.imageSmoothingQuality = "high";
  context.drawImage(background, 0, 0, canvas.width, canvas.height);

  for (const layer of result.layers) {
    const transform = normalizeTransform(layer.transform);
    if (!transform.visible) continue;
    const image = await loadImage(layer.url);
    const width = transform.width * canvas.width;
    const height = transform.height * canvas.height;
    const bounds = layer.contentBounds ?? { x: 0, y: 0, width: 1, height: 1 };
    const originX = bounds.x + bounds.width / 2;
    const originY = bounds.y + bounds.height / 2;
    const centerX = (transform.x + originX * transform.width) * canvas.width;
    const centerY = (transform.y + originY * transform.height) * canvas.height;
    context.save();
    context.translate(centerX, centerY);
    context.rotate((transform.rotation * Math.PI) / 180);
    context.scale(transform.flipX ? -1 : 1, transform.flipY ? -1 : 1);
    context.drawImage(image, -originX * width, -originY * height, width, height);
    context.restore();
  }

  return new Promise<Blob>((resolve, reject) => {
    canvas.toBlob((blob) => {
      if (blob) resolve(blob);
      else reject(new Error("Unable to export the merged image."));
    }, "image/png");
  });
}

.layer-separator {
  --ls-bg: #0d0e10;
  --ls-surface: #15171a;
  --ls-raised: #1b1d21;
  --ls-control: #22252a;
  --ls-line: rgba(255, 255, 255, 0.09);
  --ls-line-strong: rgba(255, 255, 255, 0.18);
  --ls-text: #f2f3f5;
  --ls-muted: #8d929b;
  --ls-blue: #55a9ff;
  display: grid;
  min-height: 620px;
  height: 100%;
  grid-template-rows: 62px minmax(0, 1fr);
  overflow: hidden;
  border: 1px solid var(--ls-line);
  border-radius: 16px;
  background: var(--ls-bg);
  color: var(--ls-text);
  font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  box-shadow: 0 24px 70px rgba(0, 0, 0, 0.32);
}

.layer-separator *, .layer-separator *::before, .layer-separator *::after { box-sizing: border-box; }
.layer-separator button, .layer-separator textarea, .layer-separator input { font: inherit; }
.layer-separator button { color: inherit; }
.layer-separator button:focus-visible, .layer-separator textarea:focus-visible, .layer-separator input:focus-visible { outline: 2px solid rgba(130, 190, 255, 0.8); outline-offset: 2px; }
.layer-separator button:disabled { cursor: not-allowed; opacity: 0.35; }

.layer-separator__header { display: flex; align-items: center; justify-content: space-between; gap: 20px; border-bottom: 1px solid var(--ls-line); background: #121315; padding: 0 14px 0 18px; }
.layer-separator__heading { display: flex; min-width: 0; align-items: center; gap: 11px; }
.layer-separator__mark { display: grid; width: 32px; height: 32px; flex: 0 0 auto; place-items: center; border: 1px solid var(--ls-line-strong); border-radius: 9px; background: linear-gradient(145deg, #292c31, #191b1e); color: #d9eaff; }
.layer-separator__heading > span:last-child { display: grid; min-width: 0; gap: 3px; }
.layer-separator__heading strong { font-size: 13px; font-weight: 680; letter-spacing: -0.01em; }
.layer-separator__heading small { overflow: hidden; color: var(--ls-muted); font-size: 10px; text-overflow: ellipsis; white-space: nowrap; }
.layer-separator__history { display: flex; gap: 3px; }
.layer-separator__history button { display: grid; width: 32px; height: 32px; cursor: pointer; place-items: center; border: 0; border-radius: 8px; background: transparent; color: var(--ls-muted); transition: background 150ms ease, color 150ms ease; }
.layer-separator__history button:hover:not(:disabled) { background: var(--ls-control); color: var(--ls-text); }

.layer-separator__body { display: grid; min-height: 0; grid-template-columns: minmax(0, 1fr) 320px; }
.layer-separator__workspace { display: grid; min-width: 0; min-height: 0; place-items: center; overflow: hidden; background: radial-gradient(circle at 50% 35%, rgba(58, 64, 74, 0.22), transparent 43%), #0b0c0e; padding: 34px; }
.layer-separator__stage-wrap { position: relative; width: min(100%, 680px); max-height: 100%; }
